begin;
create function public.mir_estimate_staff_allowed() returns boolean language plpgsql stable security definer set search_path=pg_catalog,mir_core as $$declare org uuid;begin select organization_id into org from mir_core.account_settings where singleton;return mir_core.has_role(org,array['admin']) or (mir_core.coordination_allowed(org) and exists(select 1 from mir_core.admin_permissions where organization_id=org and user_id=auth.uid() and estimates));end$$;
revoke all on function public.mir_estimate_staff_allowed() from public,anon;grant execute on function public.mir_estimate_staff_allowed() to authenticated;
create table mir_core.estimate_followups(organization_id uuid not null references mir_core.organizations,estimate_id uuid not null references mir_estimates.requests,id uuid not null default gen_random_uuid(),owner_id uuid references auth.users,status text not null default 'new' check(status in('new','reviewing','accepted','declined')),next_followup date,revision integer not null default 1,job_id uuid,updated_at timestamptz not null default now(),primary key(organization_id,estimate_id),unique(organization_id,job_id),foreign key(organization_id,job_id) references mir_core.jobs);
alter table mir_core.estimate_followups enable row level security;revoke all on mir_core.estimate_followups from public,anon,authenticated;
create function public.mir_estimate_inbox() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,mir_core,mir_estimates as $$declare org uuid;out jsonb;begin
 if not public.mir_estimate_staff_allowed() then raise exception 'Estimations non autorisées' using errcode='42501';end if;select organization_id into org from mir_core.account_settings where singleton;
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'number',r.request_number,'source',r.payload->>'source','name',r.payload->'contact'->>'name','createdAt',r.created_at,'status',coalesce(f.status,'new'),'ownerId',f.owner_id,'nextFollowup',f.next_followup,'revision',coalesce(f.revision,0),'jobId',f.job_id) order by r.created_at desc),'[]') into out from mir_estimates.requests r left join mir_core.estimate_followups f on(f.organization_id,f.estimate_id)=(r.organization_id,r.id) where r.organization_id=org and r.state='received';return out;
end$$;
create function public.mir_estimate_followup(p_id uuid,p_status text,p_owner uuid,p_date date,p_revision integer) returns jsonb language plpgsql security definer set search_path=pg_catalog,mir_core,mir_estimates as $$declare org uuid;f mir_core.estimate_followups;begin
 if not public.mir_estimate_staff_allowed() then raise exception 'Estimations non autorisées' using errcode='42501';end if;select organization_id into org from mir_core.account_settings where singleton;
 if not exists(select 1 from mir_estimates.requests where id=p_id and organization_id=org and state='received') then raise exception 'Demande introuvable' using errcode='42501';end if;
 if p_owner is not null and not exists(select 1 from mir_core.memberships m where m.organization_id=org and m.user_id=p_owner and m.active and (m.role='admin' or (m.role='employee' and exists(select 1 from mir_core.coordination_access a join mir_core.admin_permissions x on(x.organization_id,x.user_id)=(a.organization_id,a.user_id) where a.organization_id=org and a.user_id=m.user_id and a.active and x.estimates)))) then raise exception 'Responsable non autorisé' using errcode='42501';end if;
 insert into mir_core.estimate_followups(organization_id,estimate_id) values(org,p_id) on conflict do nothing;
 select * into f from mir_core.estimate_followups where organization_id=org and estimate_id=p_id for update;
 if f.revision<>greatest(1,p_revision) then raise exception 'Suivi modifié. Actualisez.' using errcode='40001';end if;
 update mir_core.estimate_followups set status=p_status,owner_id=p_owner,next_followup=p_date,revision=revision+1,updated_at=now() where organization_id=org and estimate_id=p_id returning * into f;return to_jsonb(f);
end$$;
create function public.mir_estimate_create_job(p_id uuid,p_number text,p_name text) returns jsonb language plpgsql security definer set search_path=pg_catalog,mir_core,mir_estimates as $$declare org uuid;r mir_estimates.requests;f mir_core.estimate_followups;j mir_core.jobs;begin
 if not public.mir_estimate_staff_allowed() then raise exception 'Estimations non autorisées' using errcode='42501';end if;select organization_id into org from mir_core.account_settings where singleton;
 if not mir_core.job_manager(org) then raise exception 'Gestion des jobs requise' using errcode='42501';end if;
 select * into r from mir_estimates.requests where id=p_id and organization_id=org and state='received';if not found then raise exception 'Demande introuvable' using errcode='42501';end if;
 select * into f from mir_core.estimate_followups where organization_id=org and estimate_id=p_id for update;
 if not found or f.status<>'accepted' then raise exception 'Acceptez la demande avant de créer le chantier' using errcode='22023';end if;
 if f.job_id is not null then return jsonb_build_object('jobId',f.job_id,'alreadyCreated',true);end if;
 if length(trim(p_number)) not between 1 and 40 or length(trim(p_name)) not between 1 and 160 then raise exception 'Numéro et nom requis' using errcode='22023';end if;
 insert into mir_core.jobs(organization_id,job_number,name,delivery_address) values(org,trim(p_number),trim(p_name),concat_ws(', ',r.payload->'address'->>'street',r.payload->'address'->>'city',r.payload->'address'->>'postalCode')) returning * into j;
 update mir_core.estimate_followups set job_id=j.id,revision=revision+1,updated_at=now() where organization_id=org and estimate_id=p_id;
 return jsonb_build_object('jobId',j.id,'estimateId',p_id);
end$$;
revoke all on function public.mir_estimate_inbox(),public.mir_estimate_followup(uuid,text,uuid,date,integer),public.mir_estimate_create_job(uuid,text,text) from public,anon;grant execute on function public.mir_estimate_inbox(),public.mir_estimate_followup(uuid,text,uuid,date,integer),public.mir_estimate_create_job(uuid,text,text) to authenticated;
-- Original attachments remain in the original private bucket. No copy or mutable URL.
create function mir_core.job_estimate_file_read(path text) returns boolean language sql stable security definer set search_path=pg_catalog,mir_core,mir_estimates as $$select exists(select 1 from mir_core.estimate_followups f join mir_estimates.requests r on(r.organization_id,r.id)=(f.organization_id,f.estimate_id) cross join lateral jsonb_array_elements(r.files) x where f.job_id is not null and mir_core.job_allowed(f.organization_id,f.job_id) and path=r.id::text||'/'||(x->>'id')||'.pdf')$$;
revoke all on function mir_core.job_estimate_file_read(text) from public,anon;grant execute on function mir_core.job_estimate_file_read(text) to authenticated;
create policy mir_job_original_estimate_files on storage.objects for select to authenticated using(bucket_id='mir-estimates' and mir_core.job_estimate_file_read(name));
create function public.mir_job_original_estimate(p_job_id uuid) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,mir_core,mir_estimates as $$declare org uuid;out jsonb;begin select organization_id into org from mir_core.account_settings where singleton;if not mir_core.job_allowed(org,p_job_id) then raise exception 'Chantier inaccessible' using errcode='42501';end if;select jsonb_build_object('id',r.id,'number',r.request_number,'files',r.files,'createdAt',r.created_at) into out from mir_core.estimate_followups f join mir_estimates.requests r on(r.organization_id,r.id)=(f.organization_id,f.estimate_id) where f.organization_id=org and f.job_id=p_job_id;return out;end$$;
revoke all on function public.mir_job_original_estimate(uuid) from public,anon;grant execute on function public.mir_job_original_estimate(uuid) to authenticated;
commit;
